import React from 'react';
import {ChartKit, settings} from '@gravity-ui/chartkit';
import {GravityChartsPlugin} from '@gravity-ui/chartkit/gravity-charts';
import type {ChartData} from '@gravity-ui/chartkit/gravity-charts';

import {colorFor} from '../palette';
import type {EngineProps, TimeSeries, ValueFormatter} from '../types';

// settings.set мерджит плагины по `type`, поэтому соседний движок не затирается.
settings.set({plugins: [GravityChartsPlugin], lang: 'ru'});

export function buildSalesConfig(
  series: readonly TimeSeries[],
  formatValue: ValueFormatter,
): ChartData {
  return {
    series: {
      data: series.map((s, i) => ({
        type: 'line' as const,
        name: s.name,
        color: colorFor(i, s.color),
        lineWidth: 2,
        data: s.points.map(([x, y]) => ({x, y})),
      })),
    },
    xAxis: {type: 'datetime'},
    yAxis: [{labels: {numberFormat: undefined}, type: 'linear', labels_: undefined} as never],
    legend: {enabled: series.length > 1},
    tooltip: {valueFormat: undefined},
  } as ChartData;
}

export default function SalesEngine({series, height, formatValue}: EngineProps) {
  const data = React.useMemo(() => buildSalesConfig(series, formatValue), [series, formatValue]);
  return (
    <div style={{height}}>
      <ChartKit type="gravity-charts" data={data} />
    </div>
  );
}
