import React from 'react';
import {ChartKit, settings} from '@gravity-ui/chartkit';
import {YagrPlugin} from '@gravity-ui/chartkit/yagr';
import type {YagrWidgetData} from '@gravity-ui/chartkit/yagr';

import {alignSeries} from '../adapters';
import {colorFor} from '../palette';
import type {EngineProps, TimeSeries, ValueFormatter} from '../types';

settings.set({plugins: [YagrPlugin], lang: 'ru'});

/** Чистая функция: общая модель → конфиг Yagr (canvas, плотные ряды). */
export function buildMonitoringConfig(
  series: readonly TimeSeries[],
  formatValue: ValueFormatter,
): YagrWidgetData {
  const {timeline, columns} = alignSeries(series);
  return {
    data: {
      timeline,
      graphs: series.map((s, i) => ({
        id: s.id,
        name: s.name,
        color: colorFor(i, s.color),
        lineWidth: 1.5,
        data: columns[i],
      })),
    },
    libraryConfig: {
      chart: {select: {zoom: true}},
      axes: {
        y: {precision: 'auto', values: (_u, ticks) => ticks.map((t) => formatValue(t))} as never,
      },
      cursor: {markers: {size: 6}} as never,
      legend: {show: series.length > 1},
      tooltip: {show: true, tracking: 'sticky'} as never,
    },
  };
}

export default function MonitoringEngine({series, height, formatValue}: EngineProps) {
  const data = React.useMemo(
    () => buildMonitoringConfig(series, formatValue),
    [series, formatValue],
  );
  return (
    <div style={{height}}>
      <ChartKit type="yagr" data={data} />
    </div>
  );
}
