import {chromium} from 'playwright';
const b = await chromium.launch();
const p = await b.newPage({viewport: {width: 1200, height: 700}});
const errors = [], reqs = [];
p.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
p.on('pageerror', (e) => errors.push('PAGEERR ' + e.message));
p.on('request', (r) => /\.js$/.test(r.url()) && reqs.push(r.url().split('/').pop()));
await p.goto('http://localhost:4173/');
await p.waitForSelector('canvas, svg.gcharts, .gcharts', {timeout: 15000}).catch(() => {});
await p.waitForTimeout(1500);
const initial = reqs.filter((r) => /Yagr|GravityCharts|Engine/.test(r));
console.log('after load chunks:', initial);
await p.screenshot({path: '/tmp/pw/sales.png'});
await p.getByText('Мониторинг', {exact: true}).click();
await p.waitForSelector('.yagr-root, canvas', {timeout: 15000}).catch(() => {});
await p.waitForTimeout(1500);
console.log('after switch chunks:', reqs.filter((r) => /Yagr|GravityCharts|Engine/.test(r)));
await p.mouse.move(600, 400);
await p.waitForTimeout(500);
await p.screenshot({path: '/tmp/pw/monitoring.png'});
await p.getByText('Продажи', {exact: true}).click();
await p.waitForTimeout(1200);
await p.screenshot({path: '/tmp/pw/sales2.png'});
console.log('errors:', errors);
await b.close();
EOF
cd /tmp/pw && node check.mjs

